/**
 * NIMA 美学评分 - 串口图传验证模式（多模型通用版）
 *
 * 支持通过 model 分区烧录不同量化版本 (s16 / w8a16 / w8a8 / w8a16_pt),
 * 输入输出的 dtype (int8/int16) 与 exponent 全部从模型元数据动态读取,
 * 同一份固件适配所有版本。
 *
 * 协议（板子 <-> 电脑，通过 USB Serial JTAG）:
 *   1. 电脑发送 4 字节魔数 "IMG\n" 表示开始传图
 *   2. 电脑发送 224*224*3 = 150528 字节 RGB888 数据（行优先，RGBRGB...）
 *   3. 板子接收完 → 预处理 → 推理 → 回传:
 *        "SCORE:x.xxxx\n"            分数
 *        "TIME:pre_us=... infer_us=...\n"  板端耗时（预处理 / 纯推理）
 *
 * 启动日志里有 "MODEL:<名字>"（编译期由 -DNIMA_MODEL_NAME 注入, flash.ps1 选择的
 * 模型名会自动带上）和 "READY"。
 *
 * 图片在电脑端已 resize 到 224x224，板子只做归一化+推理。
 */
#include <stdio.h>
#include <string.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "esp_timer.h"
#include "esp_heap_caps.h"
#include "dl_model_base.hpp"

// USB Serial JTAG 直接读写
#include "driver/usb_serial_jtag.h"
#include "driver/usb_serial_jtag_vfs.h"

static const char *TAG = "nima";

#define IMG_W 224
#define IMG_H 224
#define IMG_C 3
#define IMG_BYTES (IMG_W * IMG_H * IMG_C)  // 150528

#ifndef NIMA_MODEL_NAME
#define NIMA_MODEL_NAME "unknown"
#endif

static dl::Model *s_model = NULL;
static uint8_t *s_rgb_buf = NULL;   // 接收 RGB888 (PSRAM)

// 输入量化参数（启动时从模型元数据读）
static float s_in_scale = 0;        // int = float * s_in_scale
static bool s_in_is_int8 = false;   // false = int16

// 从 USB Serial JTAG 阻塞读取 n 字节
static int read_exact(uint8_t *buf, int n)
{
    int got = 0;
    while (got < n) {
        int r = usb_serial_jtag_read_bytes(buf + got, n - got, pdMS_TO_TICKS(5000));
        if (r <= 0) {
            return got; // 超时
        }
        got += r;
    }
    return got;
}

// 等待魔数 "IMG\n"
static bool wait_for_magic(void)
{
    const char magic[4] = {'I', 'M', 'G', '\n'};
    int match = 0;
    uint8_t c;
    while (match < 4) {
        int r = usb_serial_jtag_read_bytes(&c, 1, pdMS_TO_TICKS(1000));
        if (r <= 0) return false;
        if (c == (uint8_t)magic[match]) {
            match++;
        } else {
            match = (c == 'I') ? 1 : 0;
        }
    }
    return true;
}

// 预处理: RGB888 [0,255] -> [-1,1] -> 量化整数 (int8 或 int16, 按 s_in_* 配置)
static int64_t preprocess_and_feed(void)
{
    int64_t t0 = esp_timer_get_time();
    const int N = IMG_W * IMG_H * IMG_C;
    if (s_in_is_int8) {
        auto input_tensor = s_model->get_inputs().begin()->second;
        int8_t *p = (int8_t *)input_tensor->get_element_ptr();
        for (int i = 0; i < N; i++) {
            int v = (int)lroundf(((float)s_rgb_buf[i] / 127.5f - 1.0f) * s_in_scale);
            if (v > 127) v = 127;
            if (v < -127) v = -127;
            p[i] = (int8_t)v;
        }
    } else {
        auto input_tensor = s_model->get_inputs().begin()->second;
        int16_t *p = (int16_t *)input_tensor->get_element_ptr();
        for (int i = 0; i < N; i++) {
            int v = (int)lroundf(((float)s_rgb_buf[i] / 127.5f - 1.0f) * s_in_scale);
            if (v > 32767) v = 32767;
            if (v < -32767) v = -32767;
            p[i] = (int16_t)v;
        }
    }
    return esp_timer_get_time() - t0;
}

// 取输出分数: int8/int16 动态解码, float = raw * 2^exponent
static float decode_score(void)
{
    auto &outputs = s_model->get_outputs();
    if (outputs.empty()) {
        return NAN;
    }
    auto out = outputs.begin()->second;
    int exp = out->get_exponent();
    float factor = powf(2.0f, (float)exp);
    if (out->get_dtype() == DATA_TYPE_INT8) {
        return (float)(*((int8_t *)out->get_element_ptr())) * factor;
    }
    return (float)(*((int16_t *)out->get_element_ptr())) * factor;
}

extern "C" void app_main(void)
{
    ESP_LOGI(TAG, "=== NIMA Score - Serial Image Test (multi-model) ===");
    ESP_LOGI(TAG, "MODEL:%s", NIMA_MODEL_NAME);

    // 初始化 USB Serial JTAG driver（用于二进制图传）
    usb_serial_jtag_driver_config_t usb_cfg = {
        .tx_buffer_size = 1024,
        .rx_buffer_size = 4096,
    };
    usb_serial_jtag_driver_install(&usb_cfg);

    // 加载模型（model 分区里烧的是什么就跑什么）
    s_model = new dl::Model("model", fbs::MODEL_LOCATION_IN_FLASH_PARTITION);
    auto &inputs = s_model->get_inputs();
    if (inputs.empty()) {
        ESP_LOGE(TAG, "MODEL_LOAD_FAILED: 分区里没有可用模型 (检查 flash.ps1 -Model 是否烧对)");
        while (1) vTaskDelay(pdMS_TO_TICKS(10000));
    }
    auto input_tensor = inputs.begin()->second;
    int input_size = input_tensor->get_size();
    int in_exp = input_tensor->get_exponent();
    dtype_t in_dtype = input_tensor->get_dtype();
    s_in_scale = powf(2.0f, -(float)in_exp);
    s_in_is_int8 = (in_dtype == DATA_TYPE_INT8);

    auto &outputs = s_model->get_outputs();
    auto out_tensor = outputs.begin()->second;
    ESP_LOGI(TAG, "Model OK. Input: dtype=%s exp=%d size=%d | Output: dtype=%s exp=%d",
             input_tensor->get_dtype_string(), in_exp, input_size,
             out_tensor->get_dtype_string(), out_tensor->get_exponent());

    // 分配 RGB 接收缓冲
    s_rgb_buf = (uint8_t *)heap_caps_malloc(IMG_BYTES, MALLOC_CAP_SPIRAM);
    if (!s_rgb_buf) {
        ESP_LOGE(TAG, "Failed to alloc RGB buffer!");
        while (1) vTaskDelay(pdMS_TO_TICKS(10000));
    }

    ESP_LOGI(TAG, "READY");  // 电脑端等这个信号

    while (1) {
        // 等待图片头
        if (!wait_for_magic()) {
            continue;
        }

        // 接收 RGB 数据
        int got = read_exact(s_rgb_buf, IMG_BYTES);
        if (got != IMG_BYTES) {
            printf("ERROR:incomplete_%d\n", got);
            fflush(stdout);
            continue;
        }

        // 预处理 + 推理（分别计时）
        int64_t pre_us = preprocess_and_feed();
        int64_t t0 = esp_timer_get_time();
        s_model->run();
        int64_t infer_us = esp_timer_get_time() - t0;

        // 回传分数和耗时
        printf("SCORE:%.4f\n", decode_score());
        printf("TIME:pre_us=%lld infer_us=%lld\n", (long long)pre_us, (long long)infer_us);
        fflush(stdout);
    }
}

