/*
 * TFLite Micro Kernel 诊断工具
 *
 * 编译运行后，打印每个算子用的 kernel 实现
 * 如果看到 "reference" 说明没用优化 kernel
 */

#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
#include "tensorflow/lite/schema/schema_generated.h"

// 假设你的 .tflite 模型已加载到 model_data
extern const unsigned char model_data[];
extern const int model_data_len;

void diagnose_kernels() {
    // 1. 创建 resolver（注册算子）
    static tflite::MicroMutableOpResolver<10> resolver;
    resolver.AddConv2D();
    resolver.AddDepthwiseConv2D();
    resolver.AddFullyConnected();
    // ... 添加你模型用到的其他算子

    // 2. 加载模型
    const tflite::Model* model = tflite::GetModel(model_data);

    // 3. 创建解释器
    constexpr int kTensorArenaSize = 300 * 1024;  // 300KB
    static uint8_t tensor_arena[kTensorArenaSize];

    static tflite::MicroInterpreter interpreter(
        model, resolver, tensor_arena, kTensorArenaSize);

    interpreter.AllocateTensors();

    // 4. 检查每个节点的 kernel
    printf("=== TFLite Kernel Diagnosis ===\n");

    for (size_t i = 0; i < interpreter.operators_size(); ++i) {
        TfLiteNode* node = &interpreter.node(i);
        const TfLiteRegistration* reg = interpreter.node_registration(i);

        // 打印算子类型
        printf("Op %zu: builtin_code=%d", i, reg->builtin_code);

        // 检查是否是优化实现（通过 custom_name 判断）
        if (reg->custom_name) {
            printf(", custom_name=%s", reg->custom_name);
        }

        // 关键：检查 invoke 函数地址
        // CMSIS-NN 或优化版的函数地址会不同
        printf(", invoke=%p\n", (void*)reg->invoke);
    }

    printf("\n如果看到很多相同的 invoke 地址，说明用的是参考实现（慢）\n");
    printf("如果看到不同地址 + custom_name，说明用了优化 kernel（快）\n");
}

